"""Generate docs/SITL_STUDY_R6.md from sitl/results_r6/ (every number is read from a result file)."""
import json
import math
import os
import sys

import pandas as pd

from mission import model, replay
from . import config as cfgmod
from . import config_r6 as c6
from . import gateway as gw

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
RES = os.path.join(HERE, 'results_r6')
DOC = os.path.join(ROOT, 'docs', 'SITL_STUDY_R6.md')


def fmt(x, nd=3):
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return 'n/a'
    return f'{x:.{nd}f}'


def ci(r, nd=3):
    return f'{fmt(r.value, nd)} [{fmt(r.ci_lo, nd)}, {fmt(r.ci_hi, nd)}]'


def get(summ, p, k, metric):
    r = summ[(summ.profile == p) & (summ.config == k) & (summ.metric == metric)]
    return r.iloc[0] if len(r) else None


def table(header, rows):
    out = ['| ' + ' | '.join(header) + ' |', '|' + '---|' * len(header)]
    out += ['| ' + ' | '.join(str(x) for x in r) + ' |' for r in rows]
    return '\n'.join(out)


def round5_handshake():
    p = os.path.join(HERE, 'results', 'summary.csv')
    if not os.path.exists(p):
        return None
    s = pd.read_csv(p)
    r = s[(s.profile == 'sik') & (s.config == 'hybrid') & (s.metric == 'handshake_median_s')]
    return float(r.value.iloc[0]) if len(r) else None


def kem_auth_spread(core):
    """Run count and spread of the design K vehicle total in the 15 run RTL file (RTL simulated)."""
    p = os.path.join(ROOT, 'rtlsim', 'results', 'proto_sessions.csv')
    s = pd.read_csv(p)
    r = s[(s.core.str.lower() == core.lower()) & (s.design == c6.RTL_KEM_AUTH_ROW[0]) & (s.side == c6.RTL_KEM_AUTH_ROW[1])
          & (s.steps == c6.RTL_KEM_AUTH_ROW[2])]
    if len(r) != 1:
        return 'run spread not available'
    r = r.iloc[0]
    lo = 100 * (r.cycles_min / r.cycles_median - 1)
    hi = 100 * (r.cycles_max / r.cycles_median - 1)
    return (f"the {int(r.n_runs)} runs of its vehicle total lie from {abs(lo):.2f} percent below to {hi:.2f} percent "
            f"above their median of {r.cycles_median:.0f} cycles")


def make(res=RES, doc=DOC):
    summ = pd.read_csv(os.path.join(res, 'summary.csv'))
    pr = pd.read_csv(os.path.join(res, 'paired.csv'))
    rj = pd.read_csv(os.path.join(res, 'rejections.csv'))
    ro = pd.read_csv(os.path.join(res, 'reorder.csv'))
    dl = pd.read_csv(os.path.join(res, 'delays.csv'))
    hc = pd.read_csv(os.path.join(res, 'host_compute.csv'))
    comp = pd.read_csv(os.path.join(res, 'comparison.csv'))
    mis = pd.read_csv(os.path.join(res, 'missions.csv'))
    with open(os.path.join(res, 'environment.json')) as f:
        env = json.load(f)
    a = model.load_assumptions()
    s6 = c6.load_settings()
    s5 = cfgmod.load_settings()
    ra = replay.load_replay_assumptions()
    p_link = model.load_link_params()
    lib = env.get('libraries') or {}
    profiles = [p for p in c6.PROFILES if p in set(summ.profile)]
    L = []
    w = L.append
    w('# Software in the loop study with executed cryptography (round 6)\n')
    w('Author: Huda Mueen.\n')
    w('Status: SITL measured (round trips through ArduPilot Copter 4.7.2 running in software in the loop on the host), emulated (quantities produced by the emulated link with executed cryptography), estimated (vehicle side compute delays from RTL simulated cycles, and the mission model) and host measured (ground side compute). No timing is from flight hardware and no radio was used. Generated by `python3 -m sitl.make_doc_r6` from `sitl/results_r6/`; do not edit by hand. The round 5 study (`docs/SITL_STUDY.md`, `sitl/results/`) is unchanged.\n')
    w('## 1. Question\n')
    w('The round 5 relay carried the bytes of the hybrid session and of the per command signature and added published cycle counts as delays, but executed no cryptography and enforced no replay rule (limitation L2 of `docs/LIMITATIONS_AND_PLAN_R6.md`). This study puts a gateway pair in front of the flight stack that executes the handshake of design B with change F1 and a real per message tag with pinned libraries, enforces one of three replay acceptance rules, and compares seven configurations on paired seeds. An eighth configuration, design K (`kem_auth`: KEM authentication with static ML-KEM-768 keys pinned on both sides, X25519 plus ML-KEM-768 ephemeral exchange, no signatures, three flights; the `kem_auth` design of `rtlsim/proto/sw/proto_bench.c`), was flown afterwards on the same seeds and mission settings under the published rule.\n')
    w('## 2. Set up\n')
    w(f"- Flight stack, ground station, mission script, command stream (one COMMAND_LONG every {1 / model.command_rate('drone'):g} s from arming to disarm) and link emulation are those of round 5 (`docs/SITL_STUDY.md` section 2). Flight stack: {env.get('flight_stack')}; pymavlink {env.get('pymavlink')}; Python {env.get('python')}; host {env.get('host')}.")
    w(f"- Gateway pair (`sitl/gwrelay.py`, `sitl/gateway.py`): the ground side gateway sits between the ground station and the emulated link and the vehicle side gateway between the link and SERIAL1 of the flight stack. Both execute every cryptographic operation with pinned libraries: the Python package cryptography {lib.get('cryptography', 'n/a')} (X25519, Ed25519, SHA-256, SHAKE256) and host builds of mlkem-native (ML-KEM-768, commit {lib.get('mlkem_commit', 'n/a')}) and mldsa-native (ML-DSA-44, commit {lib.get('mldsa_commit', 'n/a')}), portable C, built by `sitl/pqlib/build.sh` and called through ctypes (`sitl/pqcrypto.py`). The protocol glue is research benchmark code and implements no primitive.")
    sz = gw.flight_sizes('hybrid')
    szc = gw.flight_sizes('classical')
    w(f"- Messages (design B with F1, `formal/models/session_b_fixed.pv`, and the glue of the RTL benchmark `rtlsim/proto/sw/proto_bench.c`): F1 = X25519 share and ML-KEM-768 encapsulation key ({sz[0]} B, ground to vehicle); F2 = X25519 share and ML-KEM-768 ciphertext ({sz[1]} B); F3 = ML-DSA-44 signature of the ground over (3, idG, idV, th) and a {gw.CONFIRM_BYTES} B confirmation tag ({sz[2]} B); F4 = the vehicle signature over (4, idV, idG, th) and its tag ({sz[3]} B); th = SHAKE256 of the transcript, the session key = SHAKE256 over both shared secrets and th. The vehicle side gateway verifies the ground signature against the pinned key, checks the confirmation tag, signs with its own key and derives the key; the ground side gateway checks the vehicle signature and tag. The classical session has the same structure with Ed25519 and no ML-KEM ({szc[0]}, {szc[1]}, {szc[2]} and {szc[3]} B). Every flight crosses the emulated link as real bytes.")
    szk = gw.flight_sizes('kem_auth')
    w(f"- Design K (`kem_auth`, the executed C reference `rtlsim/proto/sw/proto_bench.c`, section PROTO_DESIGN_KEM_AUTH): each side holds a static ML-KEM-768 key pair whose encapsulation key is pinned at the other side (generated once per run, untimed, like the long term keys of the signature designs). F1 = the ground X25519 share, a fresh ML-KEM-768 encapsulation key and a ciphertext encapsulated to the pinned vehicle static key ({szk[0]} B, ground to vehicle); F2 = the vehicle X25519 share, a ciphertext to the fresh key, a ciphertext to the pinned ground static key and the vehicle confirmation tag ({szk[1]} B); F3 = the ground confirmation tag ({szk[2]} B). The transcript hash covers both identities, F1 and F2 without its tag; the session key is SHAKE256 over the X25519 secret, the three ML-KEM secrets (vehicle static, ground ephemeral, ground static) and the transcript hash. The ground side gateway accepts after checking the vehicle tag and tags the uplink from then on; the vehicle side gateway accepts after checking F3. The handshake time of this configuration runs from F1 to the acceptance by the vehicle side gateway (both sides then hold the key), the point that corresponds to the acceptance of F4 by the ground in the signature designs. A link layer give up of F3 starts a new handshake.")
    w(f"- Per message tag: the {int(p_link['mav_sig_field_bytes'])} B MAVLink 2 signing field (link id, a 6 B counter in the timestamp field, a 6 B tag = first 6 B of SHA-256 over key, frame, link id and counter, the formula of the MAVLink 2 signing guide) added by the sending gateway to every frame and checked by the receiving gateway before the frame is forwarded; the flight stack receives the unsigned frame. Link id 0 carries every uplink frame that the link layer retransmits (commands, mode changes, mission upload) and is checked under the configured rule; link id 1 carries the ground heartbeat (not retransmitted) under the published rule; downlink frames are checked under the published rule.")
    w(f"- Replay rules: published (counter greater than the last accepted, gaps allowed); strict (only the next counter); replay cache (unseen counter inside a window of W = {int(ra['replay_window_counters'])} counters, `mission/replay_assumptions.csv`). These are the definitions of the mission model (`mission/replay.py`, `docs/MISSION_STUDY.md` Section 6.1). Strict resynchronisation: the ground side gateway starts a new handshake when its link layer gives up a frame of link id 0, or when the vehicle side gateway asks for it (an authenticated 24 B request) because a counter above the next one was seen and the next one did not arrive within the give up span of {fmt((p_link['max_retries'] + 1) * cfgmod.link_profile('sik')['rto'], 2)} s on SiK ((maximum retries + 1) times the retransmission timeout). The new handshake resets both counters.")
    w(f"- ML-DSA-44 per command: the ground side gateway signs every command frame and the vehicle side gateway verifies it; the frame carries {int(p_link['mldsa44_sig_bytes'])} B more and is sent in file transfer style chunks as in round 5. Like architecture C of the mission study, it carries no counter and enforces no replay rule.")
    ka_spread = kem_auth_spread(s6['rtl_core'])
    w(f"- Compute delays: vehicle side operations are executed on the host, and their output is released at the input time plus a delay estimated from RTL simulated cycles of the round 6 RTL runs (`rtlsim/results/proto_sessions.csv` and `proto_primitives.csv`, core {s6['rtl_core']}, {s6['rtl_statistic']} of the runs) at {a['clock_hz'] / 1e6:g} MHz, the mission study clock; the host speed enters only when the host is slower than the delay (counted in the host compute section). Ground side compute is executed on the host and enters the timings as host measured. For design K the delays come from the 15 run files of the same folder (`rtlsim/results/proto_sessions.csv` and `proto_primitives.csv`, which hold its rows; the five run snapshots used for the first seven configurations, `proto_sessions_runs5.csv` and `proto_primitives_runs5.csv`, do not), core {s6['rtl_core']} at the same clock. Design K has no signing rejection loop, so its cycles are nearly deterministic ({ka_spread}); the per message delays are the same in both sets of files.\n")
    du = dl[dl.used_in_runs == 1]
    do = dl[dl.used_in_runs == 0].set_index('name')
    oc = do.core.iloc[0] if len(do) else None
    rows = [(r['name'], f"{r['cycles']:.0f}", fmt(r['delay_ms'], 3),
             fmt(do.loc[r['name'], 'delay_ms'], 3) if oc and r['name'] in do.index else 'n/a', r['source']) for _, r in du.iterrows()]
    w(table(['delay', f"cycles on {s6['rtl_core']} (RTL simulated)", f"delay ms at {a['clock_hz'] / 1e6:g} MHz, used (estimated from RTL simulated cycles)",
             f"delay ms on {oc}, not used (estimated)" if oc else 'other core', 'source rows (rtlsim/results/)'], rows))
    w('\nThe session file gives the vehicle total of a handshake; it is split into the step before F2 (X25519 key generation and shared secret, ML-KEM-768 encapsulation for the hybrid, transcript hash and key derivation, costed from `proto_primitives.csv`) and the step before F4 (the rest of the total). The tag check uses the full receive path of a signed COMMAND_LONG; the downlink tag uses the tag of a 60 B frame. For design K the vehicle total is split the same way: the step before F2 (X25519 key generation and shared secret, one ML-KEM-768 decapsulation, two encapsulations, the transcript hash, the key derivation and the vehicle confirmation tag, costed from `proto_primitives.csv`) and the accept step (the rest of the total: the ground confirmation tag and its comparison).')
    w('')
    w(f"- Outages and seeds: one outage per mission starting uniformly between {s5['outage_window_start_s']:g} s and {s5['outage_window_end_s']:g} s after arming with an exponential duration of mean {a['outage_mean_s']:g} s (round 5 design). Mission i on a profile uses seed {int(s6['seed_base_r6'])} plus 1000 times the profile index plus i in every configuration, so the outages, the command phases and the start state of the channel loss generator are paired across configurations; every seed is stored in `sitl/results_r6/missions.csv`.\n")
    rows = [(c6.CONFIG_NAMES[k], ('mission study ' + c6.STUDY[k][0] if c6.STUDY[k][0] else 'no mission study architecture (design K)')
             + (f", {c6.STUDY[k][1]} rule" if c6.STUDY[k][1] else '')) for k in c6.CONFIGS]
    w(table(['configuration', 'compared with'], rows))
    w('')
    for pi, p in enumerate(profiles):
        name = cfgmod.PROFILE_NAMES[p]
        w(f'## {3 + 2 * pi}. Results, {name}\n')
        rows = []
        for k in c6.CONFIGS:
            if get(summ, p, k, 'missions') is None:
                continue
            hs = get(summ, p, k, 'handshake_median_s')
            add = get(summ, p, k, 'added_latency_rt_ms')
            rows.append((c6.CONFIG_NAMES[k], f"{int(get(summ, p, k, 'missions_completed').value)} of {int(get(summ, p, k, 'missions').value)}",
                         int(get(summ, p, k, 'commands').value), ci(get(summ, p, k, 'availability_rt_all'), 4),
                         ci(get(summ, p, k, 'availability_rt_link_up'), 4), fmt(get(summ, p, k, 'latency_rt_median_ms').value, 1),
                         ci(add, 1) if add is not None else 'n/a', ci(hs, 3) if hs is not None else 'n/a'))
        w(table(['configuration', 'missions completed', 'commands', 'acknowledged within 0.5 s, outages included [95% CI]',
                 'acknowledged within 0.5 s, link up [95% CI]', 'median round trip ms', 'added round trip ms against none [95% CI]',
                 'median handshake s [95% CI] (emulated)'], rows))
        w('\n_SITL measured except the handshake (emulated link with executed cryptography and delays estimated from RTL simulated cycles). Intervals: 95 percent cluster bootstrap over missions; the added round trip is paired by mission._\n')
        r5 = round5_handshake()
        hs = get(summ, p, 'hybrid_published', 'handshake_median_s')
        if p == 'sik' and r5 is not None and hs is not None:
            w(f"Hybrid handshake with executed cryptography (published rule configuration): median {fmt(hs.value, 3)} s against {fmt(r5, 3)} s for the round 5 relay with emulated delays (`sitl/results/summary.csv`), a ratio of {fmt(hs.value / r5, 3)}.\n")
        hk = get(summ, p, 'kem_auth', 'handshake_median_s')
        if hs is not None and hk is not None:
            w(f"Design K handshake (three flights, {sum(gw.flight_sizes('kem_auth'))} B in all against {sum(gw.flight_sizes('hybrid'))} B for the hybrid session): median {ci(hk, 3)} s against {ci(hs, 3)} s for the hybrid session with F1 under the same rule, a ratio of {fmt(hk.value / hs.value, 3)} (emulated).\n")
        w(f'### {3 + 2 * pi}.1 Paired differences between configurations\n')
        d = pr[pr.profile == p]
        rows = [(c6.CONFIG_NAMES[r.config], c6.CONFIG_NAMES[r.minus_config], f"{fmt(r.difference, 4)} [{fmt(r.ci_lo, 4)}, {fmt(r.ci_hi, 4)}]", int(r.missions_paired)) for r in d.itertuples()]
        w(table(['configuration', 'minus configuration', 'difference of the share acknowledged within 0.5 s, outages included [95% CI]', 'missions paired'], rows))
        w('\n_SITL measured; paired bootstrap over mission indices (the same seed in both configurations)._\n')
        w(f'### {3 + 2 * pi}.2 Commands not acknowledged within 0.5 s and frames rejected\n')
        d = rj[rj.profile == p]
        rows = [(c6.CONFIG_NAMES.get(r.config, r.config), r.scope, r.reason, int(r['count']), r.label) for _, r in d.iterrows()]
        w(table(['configuration', 'scope', 'reason', 'count', 'label'], rows))
        w('\nReasons: `link_up` the link layer gave the command up; `no_session` the ground side gateway had no session (handshake, teardown or resynchronisation in progress); `rejected_<reason>` the vehicle side gateway rejected the frame (`late_or_duplicate` published rule, `ahead_of_next` or `behind_next` strict rule, `outside_window` or `duplicate` replay cache, `bad_tag` or `bad_signature` check failed); `not_acknowledged_by_vehicle` delivered but not answered by the flight stack; the remaining commands were acknowledged later than 0.5 s or rejected by the flight stack.\n')
        d = ro[ro.profile == p]
        if len(d):
            rows = [(c6.CONFIG_NAMES[r.config], int(r.arrivals), int(r.arrivals_after_higher_counter), int(r.max_reorder_depth)) for r in d.itertuples()]
            w(f'Out of order arrivals on link id 0 at the vehicle side gateway (emulated), {name}:\n')
            w(table(['configuration', 'frames arrived', 'frames that arrived after a higher counter of the same key', 'largest distance below the highest counter seen'], rows))
            w('')
        w(f'## {4 + 2 * pi}. Comparison with the mission model per rule, {name}\n')
        d = comp[comp.profile == p]
        rows = [(c6.CONFIG_NAMES[r.config], (r.mission_arch if isinstance(r.mission_arch, str) else 'no architecture') + (f", {r.mission_rule}" if isinstance(r.mission_rule, str) and r.mission_rule else ''), r.quantity,
                 f"{fmt(r.value, 4)} [{fmt(r.ci_lo, 4)}, {fmt(r.ci_hi, 4)}]", r.label, fmt(r.mission_model_estimated, 4), fmt(r.error, 4), r.verdict)
                for r in d.itertuples()]
        w(table(['configuration', 'mission model architecture, rule', 'quantity', 'this study [95% CI]', 'label', 'mission model (estimated)', 'error', 'verdict'], rows))
        w('\nThe mission model values for availability are those of the outage rate sweep at 60 per hour (the round 5 comparison point; `mission/results/replay_outage_sweep.csv` per rule, `mission/results/sweeps.csv` for the configurations without a rule). "consistent" means the model value lies inside the 95 percent interval of this study. The handshake row applies the mission transfer model to the executed flight sizes and the RTL delays. The mission model has no architecture for design K, so its row carries no model value and no verdict.\n')
    nx = 3 + 2 * len(profiles)
    w(f'## {nx}. Host compute (host measured)\n')
    d = hc[hc.config.isin(c6.FIRST)].groupby(['side', 'operation']).agg(count=('count', 'sum'), host_mean_ms=('host_mean_ms', 'mean'),
                                              host_max_ms=('host_max_ms', 'max'), rtl_delay_ms=('delay_ms_estimated', 'max'),
                                              exceeds=('host_exceeds_rtl_delay', 'sum')).reset_index()
    rows = [(r.side, r.operation, int(r['count']), fmt(r.host_mean_ms, 3), fmt(r.host_max_ms, 3),
             fmt(r.rtl_delay_ms, 3) if r.side == 'vehicle' else 'not applied', int(r.exceeds) if r.side == 'vehicle' else 'n/a') for _, r in d.iterrows()]
    w(table(['side', 'operation', 'count', 'host mean ms (host measured)', 'host maximum ms', 'delay applied ms (estimated)', 'host slower than the delay'], rows))
    w('\n_The first seven configurations together._\n')
    dk = hc[hc.config.isin(c6.ADDED)]
    if len(dk):
        rows = [(r.side, r.operation, int(r['count']), fmt(r.host_mean_ms, 3), fmt(r.host_max_ms, 3),
                 fmt(r.delay_ms_estimated, 3) if r.side == 'vehicle' else 'not applied',
                 int(r.host_exceeds_rtl_delay) if r.side == 'vehicle' else 'n/a') for _, r in dk.sort_values(['side', 'operation']).iterrows()]
        w(table(['side', 'operation (design K)', 'count', 'host mean ms (host measured)', 'host maximum ms', 'delay applied ms (estimated)', 'host slower than the delay'], rows))
        w('\n_Design K (`kem_auth`) alone._\n')
    w('Where the host was slower than the delay, the output left at the host time, so for those events the host speed entered the result.\n')
    w(f'## {nx + 1}. Limits\n')
    w('- The emulated link is not a radio; loss is independent per frame, outages are scripted, and the channel is a first in first out queue with link layer retransmission that can deliver frames out of order (round 5 design).')
    w('- Vehicle side compute delays are RTL simulated cycles of an open RISC-V core at an assumed clock, not cycles of a flight controller; the host executes the operations for correctness only.')
    w('- The gateways are research glue in one host process around pinned libraries; secrets are not wiped and nothing was reviewed for side channels. They are not a design for use.')
    w('- Resynchronisation under the strict rule is modelled as a full new handshake; the rekey of the design (two flights protected by the current key) would be shorter.')
    w('- The ML-DSA-44 per command configuration carries no counter, as in the mission study, so it has no replay protection.')
    w('- Design K was flown after the first seven configurations, alone (one vehicle instance), while the first seven ran two instances at a time; it uses the same seeds, missions, link profile, flight stack build, libraries and interpreter, but the host load and the time of the run differ. Its vehicle side delays come from the 15 run RTL files rather than the five run snapshots. The mission model has no architecture for it, so it is compared with the other configurations of this study only.')
    w(f"- {int(s6['missions_per_config_r6'])} missions per configuration and profile give wide intervals for rare events (resynchronisations, teardowns); host scheduling noise of a shared two core host enters every round trip.\n")
    w(f'## {nx + 2}. Reproduce\n')
    w('```\nsh sitl/fetch.sh                        # flight stack at the pinned tag\nsh sitl/pqlib/build.sh                  # mlkem-native and mldsa-native host libraries at the pinned commits\nsh sitl/run_all_r6.sh <rtl results>     # eight configurations, paired seeds (kem_auth alone, last)\npython3 -m sitl.analyse_r6 && python3 -m sitl.make_doc_r6\npython3 -m unittest discover -s sitl -t .\n```\n')
    with open(doc, 'w') as f:
        f.write('\n'.join(L))
    print('wrote', doc)
    return 0


if __name__ == '__main__':
    sys.exit(make())
